-- Seed data for the lab4 cache-vs-no-cache demo.
-- Invented product catalog data, executed by the Lambda function on cold
-- start (idempotent) and once explicitly by Terraform right after deploy.

CREATE TABLE IF NOT EXISTS items (
    id          INTEGER PRIMARY KEY,
    name        TEXT NOT NULL,
    description TEXT NOT NULL,
    price       NUMERIC(10, 2) NOT NULL
);

ON CONFLICT (id) DO NOTHING;
